	/** 
	 * jumpstart the process by instantiating2 Payout
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		payoutId = PayoutService.getPayoutInstance()
		.createPayout( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		PayoutService.getPayoutInstance()
				.createPayout( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.payoutSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Payout : " + successValue.getPayoutId());
							  if (successValue.getPayoutId().equals(payoutId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfPayoutList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Payout test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on payout consumed")
					);
			subscriber.payoutSubscribe( payoutId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Payout : " + successValue.getPayoutId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfPayoutList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on payout for payoutId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Payout. 
	 */
	protected Payout read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Payout" );

		Payout entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Payout with primary key" );
		msg.append( payoutId );
		
		PayoutFetchOneSummary fetchOneSummary = new PayoutFetchOneSummary( payoutId );

		try {
			entity = PayoutService.getPayoutInstance().getPayout( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Payout " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Payout.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Payout." );

		StringBuilder msg = new StringBuilder( "Failed to update a Payout : " );        
		Payout entity = read();
		UpdatePayoutCommand command = generateUpdateCommand();
		command.setPayoutId(entity.getPayoutId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Payout." );

			// for use later on...
			payoutId = entity.getPayoutId();

			PayoutService proxy = PayoutService.getPayoutInstance();  

			proxy.updatePayout( command ).get();

			LOGGER.info( "-- Successfully saved Payout - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + payoutId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Payout.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Payout." );

		Payout entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Payout with id " + payoutId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Payout with id " + payoutId );

			throw e;
		}

		try{
			PayoutService.getPayoutInstance().delete( new DeletePayoutCommand( entity.getPayoutId() ) ).get();
			LOGGER.info( "-- Successfully deleted Payout with id " + payoutId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Payout with id " + payoutId );

			throw e;
		}
	}

	/**
	 * get all Payouts.
	 */
	protected List<Payout> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Payouts:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Payout : " );        
		List<Payout> collection  = new ArrayList<>();

		try {
			// call the static get method on the PayoutService
			collection = PayoutService.getPayoutInstance().getAllPayout();
			assertNotNull( collection, "An Empty collection of Payout was incorrectly returned.");
			
			// Now print out the values
			Payout entity = null;            
			Iterator<Payout> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getPayoutId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

